  ('waverly-hills-sanatorium', 'Waverly Hills Sanatorium', 'A former tuberculosis hospital in Louisville, Kentucky, known for its ''body chute'' and ghost tours.', 'North America', 'US', 'United States', 'Kentucky', 'Louisville', 'Hospital or sanatorium', 'Guided tour', 'SDF', 15, NULL, NULL, NULL, 'knowledge/north-america/united-states/waverly-hills-sanatorium.md'),
