INSERT INTO destination_pages (destination_id, overview, getting_there, visiting) VALUES
  ('al-jazirat-al-hamra', 'Al Jazirat Al Hamra, "the red island", is a former pearling and fishing village on the coast of Ras Al Khaimah, the northernmost emirate of the United Arab Emirates. For centuries its people lived from the sea, diving for pearls in summer and fishing and trading the rest of the year, in houses built of coral stone and beach rock with wind towers and courtyards. When the natural pearl trade collapsed and oil transformed the region, the inhabitants moved to modern houses elsewhere, and by the late 1960s and 1970s the village was abandoned. Its mosque, fort, market and houses remained, forming one of the best-preserved traditional coastal towns in the Gulf, and local legend said it was haunted by jinn. In recent years the emirate has restored parts of the village, which now hosts heritage events and an art festival, while other houses remain in ruins.', '- **Plane:** Ras Al Khaimah International Airport (RKT) is about 20 km away. Dubai International (DXB), about 70 km away, has many more flights.
